values
  ($t$0110$t$, $t$Folsom Borough$t$, $t$ATLANTIC$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough Zoning Official (Frank Sacco, Zoning/Code Enforcement Official)","Contact: Frank Sacco, Zoning/Code Enforcement Official · 609-561-3178 · fsacco@folsomborough.com","How to apply: Contact the Borough Zoning Official, Frank Sacco, at Borough Hall (1700 Rt 54) to request the certificate of continued occupancy and pay the $25 fee. He holds office hours Mondays 5:00 to 7:00 PM. The Borough code does not publish a form, a lead time or the exact sale trigger, so call ahead to confirm.","Property must meet the Borough Property Maintenance Code (2018 International Property Maintenance Code, Chapter 151)","Rental units: a current CCO must be attached to the Borough landlord registration (Chapter 152)"]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy","amount":"$25"}]$j$::jsonb, null, $t$https://folsomborough.com/services/construction.asp$t$, $j$[{"url":"https://ecode360.com/10063291","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/38657679","label":"Official source (ecode360.com)"},{"url":"https://folsomborough.com/services/construction.asp","label":"Official source (folsomborough.com)"},{"url":"https://folsomborough.com/government/directory.asp","label":"Official source (folsomborough.com)"}]$j$::jsonb, $t$The following fees in this article are under the jurisdiction of the Zoning Official but are not applicable to the uniform construction codes.$t$, $t$7f60a3a2506dfc519f2c43e2ea67374f485e631400840a7b56c26a4e3182b3cf$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0110.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0110.json$t$, true),
  ($t$0110$t$, $t$Folsom Borough$t$, $t$ATLANTIC$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (NJ DCA, state)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106 · BFCE_CSDCMAC@dca.nj.gov","Apply: More than 10 business days before closing for the lowest fee","How to apply: Apply online through the NJ DCA Fire Safety portal (Apply Smoke Certification). Pay by e-check or credit card before submitting; a valid email address is required. The certificate is emailed once the application is submitted, the fee is paid and any required inspections are done.","Fire official in the NJ state directory (NJ DCA, state), updated 7/26/2025: Louis Kilmer · (609)633-6132","Secondary power source identification label for homes with solar, generators or batteries (the State application is now the CSACMASPSIL)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://folsomborough.com/services/construction.asp","label":"Official source (folsomborough.com)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Folsom Borough$t$, $t$5320013606238a8f04a23b5eab3134508385feacef0579a93b494a010f9fe34a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0110.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0110.json$t$, true),
  ($t$0809$t$, $t$Logan Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for change of occupancy / change of ownership (Change of Owner/Occupancy Inspection)$t$, $j$["Issued by: Construction Official / Municipal Housing Inspector, Construction and Code Enforcement Department","Contact: 856-467-3424 ext. 5","How to apply: Fill out the township's Change of Owner/Occupancy Inspection Application (Chapter 119-2, rev. 04/24) and send it to the Construction Department with the fee. Checks are payable to Logan Township. Book at least 48 hours ahead to avoid the $150 rush fee. Change of Owner/Occupancy inspections are reported to be held Monday to Thursday, 12:00 pm to 2:00 pm."]$j$::jsonb, $j$[{"label":"Initial inspection","amount":"$75"},{"label":"Inspection with less than 48 hours notice","amount":"$150"},{"label":"Re-inspection","amount":"$50"},{"label":"Temporary CO (TCO) inspection","amount":"$30"}]$j$::jsonb, $t$https://uvkvaxljhhngydvlrzom.supabase.co/storage/v1/object/public/town-info-evidence/0809/622ccd21-2fe0-471c-a95e-3dce149525df/Change-Of-Owner-Occupancy-Application-2024.pdf$t$, $t$https://www.logan-twp.org/departments/construction-and-code-enforcement/$t$, $j$[{"url":"https://ecode360.com/8046096","label":"Official source (ecode360.com)"},{"url":"https://www.logan-twp.org/departments/construction-and-code-enforcement/","label":"Official source (logan-twp.org)"},{"url":"https://uvkvaxljhhngydvlrzom.supabase.co/storage/v1/object/public/town-info-evidence/0809/622ccd21-2fe0-471c-a95e-3dce149525df/Change-Of-Owner-Occupancy-Application-2024.pdf","label":"Official source (uvkvaxljhhngydvlrzom.supabase.co)"}]$j$::jsonb, $t$Certificates of occupancy are required for human habitation of all existing dwelling units in the Township of Logan before a change in occupancy of any such unit may be effected.$t$, $t$31d5907a73055533b88c87f57450e0875be753de7e65d781f0e38c33e02493b9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":1,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0809.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0809.json$t$, true),
  ($t$0809$t$, $t$Logan Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Logan Township Fire Official (municipal local enforcing agency) (town fire bureau)","Contact: 856-467-3424","How to apply: Contact Logan Township municipal offices (125 Main Street, Bridgeport) for the smoke/CO/extinguisher certificate application.","Fire official in the NJ state directory (town), updated 7/31/2026: Scott D Oatman · (856) 467-3606 · soatman@logan-twp.org","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$M Logan Township$t$, $t$6ef498dfab222dce847d4cc1f1e9f53fcc1d7562ac1075ea064fb08846bc7134$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":1,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0809.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0809.json$t$, true)
